-- ==============================================================================
-- G-Zen Phone Store — Local SQLite Schema & Real Production Data
-- Project: Track / G-Zen Phone Store (Phnom Penh, Cambodia)
-- Target: SQLite 3 / DB Browser for SQLite / backend/data/gzen_store.sqlite
-- Zero Demo Records: Real registered users, real orders, and real repair bookings only
-- ==============================================================================

PRAGMA foreign_keys = OFF;

DROP TABLE IF EXISTS users;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS repair_bookings;
DROP TABLE IF EXISTS settings;
DROP TABLE IF EXISTS bakong_transactions;

PRAGMA foreign_keys = ON;

-- 1. TABLE DEFINITIONS

CREATE TABLE users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    role TEXT DEFAULT 'customer' CHECK (role IN ('customer', 'admin')),
    phone TEXT,
    address TEXT,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE products (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    price REAL NOT NULL DEFAULT 0.0,
    originalPrice REAL DEFAULT 0.0,
    stock INTEGER NOT NULL DEFAULT 0,
    image TEXT NOT NULL,
    images TEXT DEFAULT '[]',
    brand TEXT DEFAULT 'Tech',
    description TEXT,
    specs TEXT DEFAULT '{}',
    isFeatured INTEGER DEFAULT 0,
    rating REAL DEFAULT 4.8,
    warranty TEXT DEFAULT '1 Year Official Warranty (Cambodia)',
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    orderNumber TEXT UNIQUE NOT NULL,
    userId INTEGER REFERENCES users(id) ON DELETE SET NULL,
    guestInfo TEXT,
    items TEXT NOT NULL DEFAULT '[]',
    subtotal REAL NOT NULL DEFAULT 0.0,
    deliveryFee REAL NOT NULL DEFAULT 0.0,
    totalAmount REAL NOT NULL DEFAULT 0.0,
    shippingAddress TEXT,
    paymentMethod TEXT NOT NULL DEFAULT 'KHQR',
    paymentStatus TEXT NOT NULL DEFAULT 'Pending' CHECK (paymentStatus IN ('Pending', 'Paid', 'Failed', 'Refunded')),
    transactionRef TEXT,
    status TEXT NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'QC Testing', 'Out for Delivery', 'Delivered', 'Cancelled', 'Refunded')),
    notes TEXT,
    khqrMd5 TEXT,
    khqrString TEXT,
    khqrImage TEXT,
    khqrDeeplink TEXT,
    settlementData TEXT,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE repair_bookings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    ticketNumber TEXT UNIQUE NOT NULL,
    customerName TEXT NOT NULL,
    phone TEXT NOT NULL,
    deviceModel TEXT NOT NULL,
    serviceType TEXT NOT NULL,
    issueDescription TEXT NOT NULL,
    preferredDate TEXT,
    status TEXT DEFAULT 'Received' CHECK (status IN ('Received', 'Diagnostic', 'Waiting for Parts', 'In Progress', 'Completed', 'Cancelled')),
    estimatedPrice REAL DEFAULT 0.0,
    technicianNotes TEXT,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE settings (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    key TEXT UNIQUE NOT NULL,
    value TEXT NOT NULL,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE bakong_transactions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    md5 TEXT UNIQUE NOT NULL,
    orderNumber TEXT REFERENCES orders(orderNumber) ON DELETE CASCADE,
    amount REAL NOT NULL,
    currency TEXT NOT NULL DEFAULT 'USD',
    merchantName TEXT DEFAULT 'G-ZEN PHONE STORE',
    status TEXT DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'SUCCESS', 'EXPIRED', 'FAILED')),
    bakongHash TEXT,
    fromAccount TEXT,
    payerName TEXT,
    settledAt DATETIME,
    createdAt DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- INDEXES
CREATE INDEX idx_products_category ON products(category);
CREATE INDEX idx_products_brand ON products(brand);
CREATE INDEX idx_orders_orderNumber ON orders(orderNumber);
CREATE INDEX idx_orders_khqrMd5 ON orders(khqrMd5);
CREATE INDEX idx_orders_paymentStatus ON orders(paymentStatus);
CREATE INDEX idx_bakong_md5 ON bakong_transactions(md5);

